+  for (size_t j = 0; j < M;) {
+    const size_t vl = __riscv_vsetvl_e32m1(M - j);
+    vfloat32m1_t v  = __riscv_vle32_v_f32m1(in + j, vl);
+    v               = __riscv_vfneg_v_f32m1(v, vl);
+    v               = __riscv_vfsub_vf_f32m1(v, mmax, vl);
