+      vuint16mf2_t hb = __riscv_vreinterpret_v_f16mf2_u16mf2(h);
+      __riscv_vse16_v_u16mf2(reinterpret_cast<uint16_t*>(out + j), hb, vl);
+#endif
+    }
+    j += vl;
+  }
+}
